import"./chunk-2NFLSA4Y.js";var a={circularMotion:{theory:{concept:"[[Uniform circular motion is motion along a circle at a constant speed.]] The size of the velocity stays the same, but its direction changes all the time, so the body is accelerating. This centripetal acceleration points to the centre of the circle: a_c = v\xB2/r. It is caused by a net force towards the centre, F_c = m\xB7v\xB2/r \u2014 the tension of a string, friction on the road or gravity. Without that force the body would fly off along a tangent."},param:{radius:"Radius",speed:"Speed",mass:"Mass",timeStep:"Time step"},hint:{radius:"Distance from the centre to the moving object.",speed:"The magnitude of velocity along the circular path."},preset:{small:"Small circle",medium:"Medium circle",large:"Large circle",slow:"Slow",mediumSpeed:"Medium",fast:"Fast"},measure:{radius:"Radius",period:"Period",frequency:"Frequency",angularSpeed:"Angular speed",angle:"Position angle",acceleration:"Centripetal acceleration",force:"Centripetal force",revolutions:"Revolutions"},graph:{acceleration:"Centripetal acceleration over time",angle:"Position angle over time"},challenge:{accel8:{title:"Reach 8 m/s\xB2",description:"Set the motion so centripetal acceleration is 8 m/s\xB2.",hint:"Use a speed of 4 m/s and a radius of 2 m."},periodPi:{title:"A period of \u03C0 seconds",description:"Choose values that make one revolution take about 3.14 seconds.",hint:"Try a radius of 2 m and speed of 4 m/s."},accel4:{title:"Gentler turn",description:"Set centripetal acceleration to 4 m/s\xB2.",hint:"For example, use 2 m/s around a circle of radius 1 m."},doubleSpeed:{title:"Double the speed",description:"Raise the speed to at least 8 m/s and observe the inward acceleration.",hint:"At radius 2 m, acceleration grows with the square of speed."},force24:{title:"Centripetal force of 24 N",description:"Set the mass and motion so the inward net force is 24 N.",hint:"Try mass 3 kg, speed 4 m/s and radius 2 m."}},section:{velocity:{title:"Velocity is tangent",text:"[[At every point, velocity points along the tangent to the circle.]] The velocity arrow turns as the object travels, even though its length (speed) stays the same."},force:{title:"The inward net force",text:"[[A net force toward the centre is needed to keep the object on a circular path.]] It can be supplied by tension, friction, gravity or another interaction."},try:{title:"Try changing the values",text:"Keep the radius fixed and double the speed: centripetal acceleration becomes four times larger. Keep speed fixed and double the radius: it becomes half as large."},check:{title:"Check your understanding",text:"Does an object accelerate at constant speed? Yes: acceleration measures changes in velocity, and velocity includes direction as well as speed."}},formula:{period:"Period of one revolution",frequency:"Revolutions per second",acceleration:"Inward acceleration",angularSpeed:"Angular speed",force:"Required inward net force"},assumption:{constantSpeed:"The speed and radius are constant; speed changes and non-uniform circular motion are not modeled.",horizontal:"The path is a horizontal 2D circle; gravity and vertical motion are omitted.",scale:"The drawing is schematic and not to scale; vector arrow lengths are illustrative."}}},i={sim:a};export{i as default,a as sim};
